      <div class="st-head"><a href="#/@${t(wa.perfil.handle)}" data-act="st-perfil">${a.avatar(wa.perfil,"s")}<b>@${t(wa.perfil.handle)}</b></a><span>${B.mode==="destaque"?t(wa.titulo||"Destaque"):a.rel(ba.created_at)}</span><button type="button" class="st-x" data-act="st-fechar" aria-label="Fechar">${n("x")}</button></div>
